 if(!Csrf::verify($_POST['_csrf']??null))$error='Invalid security token.';
 else try{if(strtoupper(trim((string)($_POST['confirmation']??'')))!=='REMOVE UNPUBLISHED EVENT PROFILES')throw new RuntimeException('Type REMOVE UNPUBLISHED EVENT PROFILES to confirm.');$result=UnapprovedProfileRepairService::repair($pdo,(int)(Auth::user()['id']??0));Auth::audit((int)(Auth::user()['id']??0),'unpublished_event_profile_repair',$result,'competitor_profile',null);$message=$result['repaired'].' unpublished-event profiles removed; '.$result['skipped'].' protected or changed records skipped. Safety backup: '.$result['safety_backup'].'.';}catch(Throwable $e){$error=$e->getMessage();}
