?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unpublished Event Profile Repair</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4" style="max-width:1200px"><a href="./" class="btn btn-outline-secondary btn-sm mb-3">← Competitors</a><span class="badge text-bg-danger">SUPER ADMIN · PREVIEW FIRST</span><h1 class="h3 mt-2">Unpublished Event Profile Repair</h1><p class="text-muted">Removes Bachata or Salsa profiles created only by unpublished Live/Test scoring activity. Published history and matching manual, backup or official data-entry Special Category evidence are protected.</p><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="alert alert-info"><strong><?=(int)$preview['candidates']?></strong> repair candidates found.</div><?php if($preview['candidates']):?><form method="post" class="card border-danger mb-4" onsubmit="return confirm('Create a database backup and remove only the listed unpublished-event profiles?');"><div class="card-body"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><label class="form-label">Type REMOVE UNPUBLISHED EVENT PROFILES</label><div class="input-group"><input class="form-control" name="confirmation" required><button class="btn btn-danger">Back Up and Repair</button></div></div></form><?php endif;?><div class="table-responsive"><table class="table table-sm table-bordered bg-white"><thead><tr><th>BDC ID</th><th>Competitor</th><th>Dance</th><th>Current profile</th><th>Role</th><th>Live entries</th><th>Test entries</th><th>Protection check</th></tr></thead><tbody><?php foreach($preview['rows'] as $row):?><tr><td><code><?=e($row['bdc_id'])?></code></td><td><?=e($row['exact_name'])?></td><td><?=e(ucfirst($row['dance_style']))?></td><td><?=e(ucwords(str_replace('_',' ',$row['current_division'])))?></td><td><?=e(ucfirst($row['dance_role']))?></td><td><?=(int)$row['live_entries']?></td><td><?=(int)$row['test_entries']?></td><td><span class="badge text-bg-warning">No published or recovery evidence</span></td></tr><?php endforeach;?><?php if(!$preview['rows']):?><tr><td colspan="8" class="text-center text-muted">No unpublished-event profiles require repair.</td></tr><?php endif;?></tbody></table></div></main></body></html>
